def pre(n):
    return 0 <= n <= 250

def post(n, result):
    # Independent check: n is prime iff n >= 2 and has no divisor d with
    # 2 <= d and d*d <= n. Since n <= 250 < 256, d <= 15 suffices.
    expected = n >= 2
    for d in range(2, 16):
        if d * d <= n and n % d == 0:
            expected = False
    return result == expected
